{
  "themes": [
    {
      "machine_theme_id": "M1",
      "label": "The pub as a low-stress default space for connection",
      "one_sentence_description": "The pub serves as a comfortable, default location where male friends can relax, sit down, and have meaningful conversations free from the pressures and interruptions of daily life.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T002",
          "speaker": "Participant 5",
          "quote": "The pub, really. That's where most of it happens. You can sit down, have a drink, chat without anyone expecting you to be doing anything else."
        },
        {
          "turn_id": "T003",
          "speaker": "Participant 1",
          "quote": "so the pub becomes a bit of a release, just having that space where you can talk without interruption."
        },
        {
          "turn_id": "T004",
          "speaker": "Participant 5",
          "quote": "You just want to sit down and actually talk to someone without the phone going off or someone needing something from you."
        }
      ],
      "voiced_by": [
        "Participant 5",
        "Participant 1",
        "Participant 4"
      ]
    },
    {
      "machine_theme_id": "M2",
      "label": "Shift from youthful indulgence to quieter social experiences with age",
      "one_sentence_description": "As they get older, men's socializing shifts away from drinking to excess or trying to impress others, focusing instead on quieter, more conversational gatherings.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T003",
          "speaker": "Participant 1",
          "quote": "I mean, when we were younger it was more about going out and getting hammered, but now it's quieter. You want to actually sit and have a conversation, especially at forty-five."
        },
        {
          "turn_id": "T004",
          "speaker": "Participant 5",
          "quote": "It's the same for me at forty-seven — you're not trying to prove anything anymore, are you?"
        },
        {
          "turn_id": "T007",
          "speaker": "Participant 4",
          "quote": "at forty you're not trying to impress anyone anymore. You just want to sit down with people you know and not have to think too hard about it."
        }
      ],
      "voiced_by": [
        "Participant 1",
        "Participant 5",
        "Participant 4"
      ]
    },
    {
      "machine_theme_id": "M3",
      "label": "Value of quality pub food in enhancing the social experience",
      "one_sentence_description": "While food is not the primary reason for visiting the pub, well-sourced and properly cooked food significantly enhances the enjoyment of the evening and encourages them to stay longer.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T004",
          "speaker": "Participant 5",
          "quote": "it makes the whole experience better if it's done well. You're more inclined to stay longer, have another pint if the food's good and you're not sitting there regretting what you ate."
        },
        {
          "turn_id": "T005",
          "speaker": "Participant 1",
          "quote": "ordered a steak, and it was just... you could tell someone cared about where it came from. Not expensive or anything, just decent quality beef cooked right. Made a real difference to the evening."
        }
      ],
      "voiced_by": [
        "Participant 5",
        "Participant 1",
        "Participant 4"
      ]
    },
    {
      "machine_theme_id": "M4",
      "label": "Growing awareness of food quality paired with a practical attitude",
      "one_sentence_description": "With age comes a permanent awareness and appreciation of better-quality food, though this is balanced with a practical, non-obsessive attitude toward everyday sourcing and shopping.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T005",
          "speaker": "Participant 1",
          "quote": "And once you've noticed it, you can't unknow it, can you? You go back somewhere and you think, yeah, this is fine, but it's not the same."
        },
        {
          "turn_id": "T005",
          "speaker": "Participant 1",
          "quote": "I'm not going to pretend I'm checking where everything comes from or anything like that — I still do my shop at Tesco like everyone else."
        },
        {
          "turn_id": "T007",
          "speaker": "Participant 4",
          "quote": "But like you say, Andrew, I'm not going out of my way to source everything perfectly or anything daft like that. It's just... if I'm going to eat something, might as well be something decent if it's there."
        }
      ],
      "voiced_by": [
        "Participant 1",
        "Participant 4"
      ]
    }
  ]
  }

{
  "themes": [
    {
      "machine_theme_id": "M1",
      "label": "Social normalcy as the primary barrier",
      "one_sentence_description": "Adopting a plant-based diet is blocked more by the social discomfort of doing something different or feeling 'weird' than by the practical difficulties of cooking and eating without meat.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T029",
          "speaker": "Participant 4",
          "quote": "Because the actual cooking and eating side of it — that's easy enough. It's the other thing that's the blocker."
        },
        {
          "turn_id": "T030",
          "speaker": "Participant 1",
          "quote": "Yeah, that's the thing though, isn't it? What Isaiah's saying — the normalcy bit is the blocker."
        }
      ],
      "voiced_by": [
        "Participant 4",
        "Participant 1"
      ]
    },
    {
      "machine_theme_id": "M2",
      "label": "Unconscious collective maintenance of normalcy",
      "one_sentence_description": "The normalcy of eating meat is kept in place through a circular dynamic where individuals make the 'safe' choice and avoid questioning or discussing it, thereby reinforcing it for others.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T030",
          "speaker": "Participant 1",
          "quote": "We're all kind of maintaining it, aren't we? By not questioning it, by making the safe choice without thinking about it too much."
        }
      ],
      "voiced_by": [
        "Participant 1"
      ]
    },
    {
      "machine_theme_id": "M3",
      "label": "Conscious choice requires personal responsibility",
      "one_sentence_description": "Once individuals become aware of the social patterns surrounding meat-eating, opting for an alternative means making a conscious 'statement' that must be defended, which is harder than simply following the effortless default.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T031",
          "speaker": "Participant 4",
          "quote": "Because once you start questioning it, once you make it a choice instead of just the default, you're the one who has to own that. You can't just... not think about it anymore."
        },
        {
          "turn_id": "T032",
          "speaker": "Participant 1",
          "quote": "And that means if you actually wanted to do something different, you'd have to own it consciously. You couldn't just eat meat without thinking about it anymore because you'd know what you were doing."
        }
      ],
      "voiced_by": [
        "Participant 4",
        "Participant 1"
      ]
    },
    {
      "machine_theme_id": "M4",
      "label": "Meat-eating as an unexamined default rather than a social choice",
      "one_sentence_description": "Some individuals do not feel they are actively maintaining social norms or making symbolic choices about masculinity when eating meat; it is simply what they eat without prior thought.",
      "relevance": "secondary",
      "evidence": [
        {
          "turn_id": "T034",
          "speaker": "Participant 3",
          "quote": "I just eat meat, it's what I do, and I haven't been walking around aware that I'm choosing it for some performance reason or whatever."
        }
      ],
      "voiced_by": [
        "Participant 3"
      ]
    }
  ]
}

{
  "themes": [
    {
      "machine_theme_id": "M1",
      "label": "Spontaneous and unplanned meal selection",
      "one_sentence_description": "Meal choices are often made spontaneously based on immediate desire or what is currently available in the kitchen, rather than through structured planning.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T011",
          "speaker": "Participant 1",
          "quote": "I don't plan, plan in detail, uh, in advance or go to the supermarket specifically thinking about what days to buy. I’ll just buy various things, um, I like the look of when I'm in the supermarket and then, as and when decide to eat them."
        }
      ],
      "voiced_by": [
        "Participant 1"
      ]
    },
    {
      "machine_theme_id": "M2",
      "label": "Work schedules and time constraints dictate meal planning",
      "one_sentence_description": "Meal choices and preparation are heavily shaped by busy work schedules, long commutes, and limited energy at the end of the day.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T012",
          "speaker": "Participant 2",
          "quote": "So I'll, I'll try and have a rough plan based around what the schedule for the week is, but um equally I can get home tonight and go, you know, I can't even be assed cooking a pizza. Let's order a takeaway because, you know, hour long train journey."
        },
        {
          "turn_id": "T013",
          "speaker": "Participant 3",
          "quote": "Yeah, I'd say as well, time is quite a big factor in terms of, um, what you eat in some ways, because like, not so much a problem for now, because I'm a teacher, but during like school term time, staff meeting night, Wednesday, it's always long. So I don't really want to be spending ages cooking."
        }
      ],
      "voiced_by": [
        "Participant 2",
        "Participant 3"
      ]
    },
    {
      "machine_theme_id": "M3",
      "label": "Working from home enables greater cooking flexibility",
      "one_sentence_description": "Working from home provides individuals with the time and opportunity to prepare or cook meals during the afternoon.",
      "relevance": "secondary",
      "evidence": [
        {
          "turn_id": "T016",
          "speaker": "Participant 1",
          "quote": "perhaps if anyone works from home, they might have more chances to put something in the oven whilst they're still working and, and, and have that cooking away."
        },
        {
          "turn_id": "T018",
          "speaker": "Participant 4",
          "quote": "I actually work from home most of the time, so I can kind of cook something in the afternoon."
        }
      ],
      "voiced_by": [
        "Participant 1",
        "Participant 4"
      ]
    },
    {
      "machine_theme_id": "M4",
      "label": "Large household meals revolve around batch-cooked, universally liked food",
      "one_sentence_description": "Cooking for a large family involves making large quantities of simple, familiar meals that are guaranteed to satisfy everyone's tastes.",
      "relevance": "secondary",
      "evidence": [
        {
          "turn_id": "T018",
          "speaker": "Participant 4",
          "quote": "we've kind of got a load of meals that we know everybody, everybody'll eat. And then we tend to batch cook them."
        }
      ],
      "voiced_by": [
        "Participant 4"
      ]
    },
    {
      "machine_theme_id": "M5",
      "label": "Deferring meal choices to a cooking partner",
      "one_sentence_description": "Some individuals do not have to make meal decisions because their partner handles and enjoys the cooking entirely.",
      "relevance": "secondary",
      "evidence": [
        {
          "turn_id": "T019",
          "speaker": "Participant 5",
          "quote": "she tends to, um, make the lunches and dinners and enjoys doing so. I mean, I'll chip in where I can. Um, but as I say, I tend not to decide."
        }
      ],
      "voiced_by": [
        "Participant 5"
      ]
    }
  ]
}

{
  "themes": [
    {
      "machine_theme_id": "M1",
      "label": "Price and taste parity",
      "one_sentence_description": "Plant-based foods would become appealing if they were as cheap and tasted as good as meat options.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T033",
          "speaker": "Participant 2",
          "quote": "For me again, it's down to the price and taste. If it was, if it was cheap and tasted the same, then I'd be perfectly happy to buy it."
        },
        {
          "turn_id": "T035",
          "speaker": "Participant 3",
          "quote": "it really would come down to price if it was significantly cheaper."
        }
      ],
      "voiced_by": [
        "Participant 2",
        "Participant 3"
      ]
    },
    {
      "machine_theme_id": "M2",
      "label": "Masculinity is not a barrier",
      "one_sentence_description": "The idea that eating plant-based foods is unmanly is outdated, and men do not judge each other for choosing them.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T034",
          "speaker": "Participant 1",
          "quote": "certainly within my social group, the men aspect of it is just a, just a, we wouldn't even consider it being kind of unmanly."
        }
      ],
      "voiced_by": [
        "Participant 1"
      ]
    },
    {
      "machine_theme_id": "M3",
      "label": "Health benefits and physical fitness",
      "one_sentence_description": "Clear health benefits, such as extending one's active years and fitness, make plant-based foods more appealing.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T035",
          "speaker": "Participant 3",
          "quote": "the one that would still really resonate with me is, is just around the, the health, overall fitness."
        }
      ],
      "voiced_by": [
        "Participant 3"
      ]
    },
    {
      "machine_theme_id": "M4",
      "label": "Unhealthy additives in plant-based substitutes",
      "one_sentence_description": "Many processed meat substitutes are unappealing because they are high in sugars, salts, fats, and artificial additives.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T036",
          "speaker": "Participant 1",
          "quote": "from what I hear and what I read a lot of these plant based and substitute meals are actually, they're loaded with with with sugars and salts and fats that don't actually make them any healthier for me."
        },
        {
          "turn_id": "T039",
          "speaker": "Participant 2",
          "quote": "it's probably that that gives it its, its nicer taste, it makes it, makes it taste nice or makes it taste like what it’s trying to simulate."
        }
      ],
      "voiced_by": [
        "Participant 1",
        "Participant 2"
      ]
    },
    {
      "machine_theme_id": "M5",
      "label": "The phrase \"plant-based\" is loaded",
      "one_sentence_description": "The term \"plant-based\" feels accusatory and loaded, whereas encouraging people to eat more fruit and vegetables is a more positive message.",
      "relevance": "central",
      "evidence": [
        {
          "turn_id": "T037",
          "speaker": "Participant 3",
          "quote": "plant based just feels a really loaded, um, really loaded phrase. And actually encouraging people to eat more fruit and veg is actually a better message."
        },
        {
          "turn_id": "T038",
          "speaker": "Participant 1",
          "quote": "plant based does sound, you're right, it does sound accusatory."
        }
      ],
      "voiced_by": [
        "Participant 1",
        "Participant 3"
      ]
    },
    {
      "machine_theme_id": "M6",
      "label": "Sensory replication of meat",
      "one_sentence_description": "Processed substitutes must successfully mimic the exact taste and texture of the meat they are trying to replace to be acceptable.",
      "relevance": "secondary",
      "evidence": [
        {
          "turn_id": "T036",
          "speaker": "Participant 1",
          "quote": "Now if they came up with some sort of amazing plant based bacon that that to me tasted and had the texture of bacon, um, then maybe that would, that would steer me down that route"
        }
      ],
      "voiced_by": [
        "Participant 1"
      ]
    }
  ]
}
